// The "hard-wired" handle tables compiled into Game.exe (generated by the original tool chain
// as subanisHW.inl / tracksHW.inl). Game code never uses archive indices: it writes
//   SCURR_getSubAniSerialFromHWHandle(539 + 0x800000)   -> table 0x4A6578, 769 entries
//   SCURR_getTrackSerialFromHWHandle(1243 + 0x900000)   -> table 0x4A3C20, 1322 entries
// Each entry is { u32 serial (filled at start-up), char *name }; the name is looked up
// case-insensitively in subanis.apc / tracks.trk (FUN_004506a0, FUN_00450b30), so
// HW handle -> name -> archive index/serial. This module extracts the tables from Game.exe.

export const HW_SUBANI_BASE = 0x800000;
export const HW_TRACK_BASE = 0x900000;

export interface HwTables {
  /** subanis[n] = name of subani HW handle 0x800000 + n. */
  subanis: string[];
  /** tracks[n] = name of track HW handle 0x900000 + n. */
  tracks: string[];
  /** Direction pseudo subani names, serial 0x300000 + i (FUN_004500d0). */
  directions: string[];
  /** Tracks with a C++ callback (called with 0x100000 start, 0x400000|key, 0x200000 end): table 0x4BA2C8. */
  trackCallbacks: Array<{ track: string; fn: number }>;
  /** Track -> track played next when it ends (FUN_00451b40, table 0x4BA6C8). */
  trackFollowUps: Array<[string, string]>;
}

interface Section { va: number; vsize: number; raw: number; rawSize: number }

function sections(exe: Uint8Array): { base: number; secs: Section[] } {
  const v = new DataView(exe.buffer, exe.byteOffset, exe.byteLength);
  const pe = v.getUint32(0x3c, true);
  if (v.getUint32(pe, true) !== 0x4550) throw new Error('not a PE file');
  const nsec = v.getUint16(pe + 6, true), optSize = v.getUint16(pe + 20, true);
  const base = v.getUint32(pe + 24 + 28, true);
  const secs: Section[] = [];
  for (let i = 0; i < nsec; i++) {
    const s = pe + 24 + optSize + i * 40;
    secs.push({ va: base + v.getUint32(s + 12, true), vsize: v.getUint32(s + 8, true), raw: v.getUint32(s + 20, true), rawSize: v.getUint32(s + 16, true) });
  }
  return { base, secs };
}

export function extractHwTables(exe: Uint8Array): HwTables {
  const { secs } = sections(exe);
  const v = new DataView(exe.buffer, exe.byteOffset, exe.byteLength);
  const off = (va: number) => {
    const s = secs.find((x) => va >= x.va && va < x.va + Math.max(x.vsize, x.rawSize));
    if (!s || va - s.va >= s.rawSize) throw new Error(`VA 0x${va.toString(16)} not in file`);
    return s.raw + va - s.va;
  };
  const u32 = (va: number) => v.getUint32(off(va), true);
  const cstr = (va: number) => {
    let p = off(va), s = '';
    while (exe[p]) s += String.fromCharCode(exe[p++]);
    return s;
  };
  const table = (va: number, n: number) => Array.from({ length: n }, (_, i) => cstr(u32(va + i * 8 + 4)));
  const subanis = table(0x4a6578, 0x301);
  const tracks = table(0x4a3c20, 0x52a);
  const directions = Array.from({ length: 8 }, (_, i) => cstr(u32(0x4a3c00 + i * 4)));
  const nCb = u32(0x4ba2c0);
  const trackCallbacks = Array.from({ length: nCb }, (_, i) => ({ track: cstr(u32(0x4ba2c8 + i * 8)), fn: u32(0x4ba2cc + i * 8) }));
  const trackFollowUps: Array<[string, string]> = [];
  for (let p = 0x4ba6c8; u32(p); p += 8) trackFollowUps.push([cstr(u32(p)), cstr(u32(p + 4))]);
  // sanity checks against strings we know
  if (subanis[539] !== '_inv__###_MainGfx' || tracks[0] !== 'lillK_1c_026A1_RovarMusik') throw new Error('unexpected Game.exe (HW tables differ)');
  return { subanis, tracks, directions, trackCallbacks, trackFollowUps };
}
